def solve(s: str):
    """Run-length encoding for string s, returning list of [char, count] pairs."""
    if not s:
        return []
    result = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            result.append([cur, cnt])
            cur = ch
            cnt = 1
    result.append([cur, cnt])
    return result

