def solve(tokens):
    """Evaluate a Reverse Polish Notation expression.
    tokens: list of strings representing integers or +, -, *, /.
    Division truncates toward zero.
    """
    stack = []
    ops = {'+', '-', '*', '/'}
    for tok in tokens:
        if tok not in ops:
            stack.append(int(tok))
        else:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                stack.append(int(a / b))
    return stack[0] if stack else 0

